16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @Column(name = "household_id")
63	    private String householdId;
64	
65	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
66	    private Set<Pet> pets;
67	
68	    public String getAddress() {
69	        return this.address;
70	    }
71	
72	    public void setAddress(String address) {
73	        this.address = address;
74	    }
75	
76	    public String getCity() {
77	        return this.city;
78	    }
79	
80	    public void setCity(String city) {
81	        this.city = city;
82	    }
83	
84	    public String getTelephone() {
85	        return this.telephone;
86	    }
87	
88	    public void setTelephone(String telephone) {
89	        this.telephone = telephone;
90	    }
91	
92	    public String getEmail() {
93	        return this.email;
94	    }
95	
96	    /**
97	     * Set the owner's email address, normalizing it to lower case so it is both
98	     * stored and returned in a canonical form. A {@code null} value is left as-is.
99	     */
100	    public void setEmail(String email) {
101	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
102	    }
103	
104	    public LocalDate getRegistrationDate() {
105	        return this.registrationDate;
106	    }
107	
108	    public void setRegistrationDate(LocalDate registrationDate) {
109	        this.registrationDate = registrationDate;
110	    }
111	
112	    public String getCustomerCode() {
113	        return this.customerCode;
114	    }
115	
116	    public void setCustomerCode(String customerCode) {
117	        this.customerCode = customerCode;
118	    }
119	
120	    public String getHouseholdId() {
121	        return this.householdId;
122	    }
123	
124	    public void setHouseholdId(String householdId) {
125	        this.householdId = householdId;
126	    }
127	
128	    protected Set<Pet> getPetsInternal() {
129	        if (this.pets == null) {
130	            this.pets = new HashSet<>();
131	        }
132	        return this.pets;
133	    }
134	
135	    protected void setPetsInternal(Set<Pet> pets) {
136	        this.pets = pets;
137	    }
138	
139	    public List<Pet> getPets() {
140	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
141	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
142	        return Collections.unmodifiableList(sortedPets);
143	    }
144	
145	    public void setPets(List<Pet> pets) {
146	        this.pets = new HashSet<>(pets);
147	    }
148	
149	    public void addPet(Pet pet) {
150	        getPetsInternal().add(pet);
151	        pet.setOwner(this);
152	    }
153	
154	    /**
155	     * Return the Pet with the given name, or null if none found for this Owner.
156	     *
157	     * @param name to test
158	     * @return true if pet name is already in use
159	     */
160	    public Pet getPet(String name) {
161	        return getPet(name, false);
162	    }
163	
164	    /**
165	     * Return the Pet with the given name, or null if none found for this Owner.
166	     *
167	     * @param name to test
168	     * @return true if pet name is already in use
169	     */
170	    public Pet getPet(String name, boolean ignoreNew) {
171	        name = name.toLowerCase();
172	        for (Pet pet : getPetsInternal()) {
173	            if (!ignoreNew || !pet.isNew()) {
174	                String compName = pet.getName();
175	                compName = compName.toLowerCase();
176	                if (compName.equals(name)) {
177	                    return pet;
178	                }
179	            }
180	        }
181	        return null;
182	    }
183	
184	    public Pet getPet(Integer petId) {
185	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
186	    }
187	
188	    @Override
189	    public String toString() {
190	        return new ToStringCreator(this)
191	
192	            .append("id", this.getId())
193	            .append("new", this.isNew())
194	            .append("lastName", this.getLastName())
195	            .append("firstName", this.getFirstName())
196	            .append("address", this.address)
197	            .append("city", this.city)
198	            .append("telephone", this.telephone)
199	            .append("email", this.email)
200	            .toString();
201	    }
202	}
