17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.Collection;
24	import java.util.List;
25	import java.util.Locale;
26	
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
108	        if (normalizedTelephone == null) {
109	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
110	        }
111	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
112	            return new ResponseEntity<>(HttpStatus.CONFLICT);
113	        }
114	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
115	        List<Owner> householdMembers =
116	            findHouseholdMembers(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
117	        if (!sharesHousehold && !householdMembers.isEmpty()) {
118	            return new ResponseEntity<>(HttpStatus.CONFLICT);
119	        }
120	        HttpHeaders headers = new HttpHeaders();
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        owner.setTelephone(normalizedTelephone);
123	        if (owner.getRegistrationDate() == null) {
124	            owner.setRegistrationDate(LocalDate.now());
125	        }
126	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
127	        if (sharesHousehold && !householdMembers.isEmpty()) {
128	            String householdId = householdId(owner.getLastName(), owner.getAddress());
129	            owner.setHouseholdId(householdId);
130	            for (Owner member : householdMembers) {
131	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
132	                    member.setHouseholdId(householdId);
133	                    this.clinicService.saveOwner(member);
134	                }
135	            }
136	        }
137	        this.clinicService.saveOwner(owner);
138	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
139	        headers.setLocation(UriComponentsBuilder.newInstance()
140	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
141	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
147	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
148	        if (currentOwner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
152	        if (normalizedTelephone == null) {
153	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
154	        }
155	        currentOwner.setAddress(ownerFieldsDto.getAddress());
156	        currentOwner.setCity(ownerFieldsDto.getCity());
157	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
158	        currentOwner.setLastName(ownerFieldsDto.getLastName());
159	        currentOwner.setTelephone(normalizedTelephone);
160	        currentOwner.setEmail(ownerFieldsDto.getEmail());
161	        this.clinicService.saveOwner(currentOwner);
162	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Transactional
167	    @Override
168	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        this.clinicService.deleteOwner(owner);
174	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        HttpHeaders headers = new HttpHeaders();
185	        Pet pet = petMapper.toPet(petFieldsDto);
186	        owner.setId(ownerId);
187	        pet.setOwner(owner);
188	        pet.getType().setName(null);
189	        this.clinicService.savePet(pet);
190	        PetDto petDto = petMapper.toPetDto(pet);
191	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
192	            .buildAndExpand(pet.getId()).toUri());
193	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
199	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
200	        if (currentOwner != null) {
201	            Pet currentPet = this.clinicService.findPetById(petId);
202	            if (currentPet != null) {
203	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
204	                currentPet.setName(petFieldsDto.getName());
205	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
206	                this.clinicService.savePet(currentPet);
207	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
208	            }
209	        }
210	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	    }
212	
213	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
214	    @Override
215	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
216	        HttpHeaders headers = new HttpHeaders();
217	        Visit visit = visitMapper.toVisit(visitFieldsDto);
218	        Pet pet = new Pet();
219	        pet.setId(petId);
220	        visit.setPet(pet);
221	        this.clinicService.saveVisit(visit);
222	        VisitDto visitDto = visitMapper.toVisitDto(visit);
223	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
224	            .buildAndExpand(visit.getId()).toUri());
225	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
226	    }
227	
228	
229	    /**
230	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
231	     * stripped. When a leading {@code '+'} and country code are present they are kept;
232	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
233	     * is dropped from the national digits. The result must be a {@code '+'} followed
234	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
235	     * is returned to signal a bad request.
236	     */
237	    /**
238	     * Build the customer code for a newly created owner, formatted
239	     * {@code '<LAST3>-<NNNN>'} where {@code LAST3} is the upper-cased first three
240	     * letters of the last name and {@code NNNN} is a global 4-digit zero-padded
241	     * sequence equal to one more than the current number of owners.
242	     */
243	    private String nextCustomerCode(String lastName) {
244	        String prefix = lastName == null ? "" : lastName;
245	        prefix = prefix.substring(0, Math.min(3, prefix.length())).toUpperCase(Locale.ROOT);
246	        int sequence = this.clinicService.findAllOwners().size() + 1;
247	        return String.format("%s-%04d", prefix, sequence);
248	    }
249	
250	    /**
251	     * Find the existing owners that already belong to the same household as the given
252	     * last name and address, i.e. those sharing both fields. Both are compared
253	     * case-insensitively after collapsing runs of whitespace to a single space and
254	     * trimming the ends.
255	     */
256	    private List<Owner> findHouseholdMembers(String lastName, String address) {
257	        String normalizedLastName = normalizeForHousehold(lastName);
258	        String normalizedAddress = normalizeForHousehold(address);
259	        return this.clinicService.findAllOwners().stream()
260	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
261	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
262	            .toList();
263	    }
264	
265	    /**
266	     * Build a stable identifier shared by all owners of one household. It is derived
267	     * deterministically from the normalized last name and address, so every owner at
268	     * the same household resolves to the same value regardless of creation order.
269	     */
270	    private String householdId(String lastName, String address) {
271	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
272	        try {
273	            byte[] digest = MessageDigest.getInstance("SHA-256")
274	                .digest(key.getBytes(StandardCharsets.UTF_8));
275	            StringBuilder sb = new StringBuilder();
276	            for (int i = 0; i < 6; i++) {
277	                sb.append(String.format("%02X", digest[i]));
278	            }
279	            return "HH-" + sb;
280	        }
281	        catch (NoSuchAlgorithmException e) {
282	            throw new IllegalStateException(e);
